//! Compile a real ARMv6-M firmware with `clang` and execute it on this core.
//!
//! This is the "real firmware trace" from the M0 definition of done: instead
//! of hand-assembled bytes, the code is generated by the LLVM backend and
//! executed through the simulator. The tests build the firmware with `clang`
//! and extract the raw `.text` with `objcopy`; they skip (with a note) if the
//! toolchain binaries are not available.

use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicUsize, Ordering};

use vioarm_core::board;
use vioarm_core::device::systick::SysTick;
use vioarm_core::error::HaltCause;
use vioarm_core::loader::load_flat;
use vioarm_core::machine::Machine;
use vioarm_core::mem::bus::Bus;
use vioarm_core::mem::flat::FlatMemory;
use vioarm_core::mem::system::SystemMemory;

const FLASH: u32 = 0x0000_0000;
const RAM: u32 = 0x2000_0000;
const FLASH_LEN: u32 = 0x10000;
const RAM_LEN: u32 = 0x10000;
const CODE_BASE: u32 = 0x0000_0100;
const INIT_SP: u32 = 0x2000_8000;

const IN_ADDR: u32 = RAM;
const SUM_ADDR: u32 = RAM + 4;
const TAG_ADDR: u32 = RAM + 8;

/// A small freestanding firmware: read an input, sum 1..=n in a loop that
/// stays a loop under `-O0` (and which therefore needs no libc helpers), store
/// the sum and a sentinel, then `bkpt`.
const FIRMWARE: &str = r#"
#define IN_ADDR  0x20000000u
#define SUM_ADDR 0x20000004u
#define TAG_ADDR 0x20000008u

__attribute__((noinline)) static unsigned sum1to(unsigned n) {
    unsigned s = 0;
    for (unsigned i = 1; i <= n; ++i) s += i;
    return s;
}

void reset(void) {
    unsigned n = *(volatile unsigned *)IN_ADDR;
    unsigned s = sum1to(n);
    *(volatile unsigned *)SUM_ADDR = s;
    *(volatile unsigned *)TAG_ADDR = 0xdeadbeefu;
    __asm__ volatile("bkpt #0");
}
"#;

/// A firmware that arms `SysTick` and lets the handler run three times before
/// stopping the timer and halting.
const SYSTICK_FIRMWARE: &str = r#"
#define TICKS    0x20000000u
#define COUNT    0x20000004u
#define PERIOD   0x20000008u
#define SYST_CSR 0xE000E010u
#define SYST_RVR 0xE000E014u
#define SYST_CVR 0xE000E018u

void SysTick_Handler(void) {
    (*(volatile unsigned *)TICKS)++;
}

void reset(void) {
    *(volatile unsigned *)SYST_RVR = *(volatile unsigned *)PERIOD - 1;
    *(volatile unsigned *)SYST_CVR = 0;
    *(volatile unsigned *)SYST_CSR = 0x7; /* ENABLE | TICKINT | CLKSOURCE */
    while (*(volatile unsigned *)TICKS < 3) { }
    *(volatile unsigned *)SYST_CSR = 0; /* stop the timer */
    *(volatile unsigned *)COUNT = *(volatile unsigned *)TICKS;
    __asm__ volatile("bkpt #0");
}
"#;

/// A firmware that drives GPIO outputs, reads back host-driven inputs, and
/// transmits a line of text on the virtual UART before halting.
const IO_FIRMWARE: &str = r#"
#define OUT_SNAPSHOT 0x20000000u
#define IN_SNAPSHOT  0x20000004u
#define UART_DR 0x40001000u
#define UART_FR 0x40001004u
#define GPIO_DIR 0x40000000u
#define GPIO_OUT 0x40000004u
#define GPIO_IN  0x40000008u

static void putc(unsigned c) {
    while (!(*(volatile unsigned *)UART_FR & 1u)) { }
    *(volatile unsigned *)UART_DR = c;
}

void reset(void) {
    *(volatile unsigned *)GPIO_DIR = 0xFFu; /* pins 0..7 outputs */
    *(volatile unsigned *)GPIO_OUT = 0xAAu;
    *(volatile unsigned *)OUT_SNAPSHOT = *(volatile unsigned *)GPIO_OUT;
    *(volatile unsigned *)IN_SNAPSHOT = *(volatile unsigned *)GPIO_IN;
    putc('H'); putc('i'); putc('!'); putc('\n');
    __asm__ volatile("bkpt #0");
}
"#;

static SEQ: AtomicUsize = AtomicUsize::new(0);
/// Find an executable by name on `PATH`.
fn which(name: &str) -> Option<PathBuf> {
    env::var_os("PATH").and_then(|paths| {
        env::split_paths(&paths)
            .map(|dir| dir.join(name))
            .find(|path| path.is_file())
    })
}

/// Run a tool, capturing stdout; `Err` on spawn or non-zero exit.
fn run(tool: &Path, args: &[&str]) -> Result<String, String> {
    let out = Command::new(tool)
        .args(args)
        .output()
        .map_err(|e| format!("cannot run {}: {e}", tool.display()))?;
    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr);
        return Err(format!("{} failed: {stderr}", tool.display()));
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

/// Compile `source` and return `(.text bytes, symbol -> offset within .text)`.
fn build_firmware(source: &str) -> Result<(Vec<u8>, HashMap<String, u32>), String> {
    let clang = which("clang").ok_or_else(|| "clang not found on PATH".to_string())?;
    let objcopy = which("llvm-objcopy")
        .or_else(|| which("objcopy"))
        .ok_or_else(|| "objcopy not found on PATH".to_string())?;
    let nm = which("llvm-nm")
        .or_else(|| which("nm"))
        .ok_or_else(|| "nm not found on PATH".to_string())?;

    let dir = env::temp_dir().join(format!("vioarm-fw-{}", SEQ.fetch_add(1, Ordering::Relaxed)));
    fs::create_dir_all(&dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    let src = dir.join("firmware.c");
    let obj = dir.join("firmware.o");
    fs::write(&src, source).map_err(|e| e.to_string())?;

    let src = src.to_str().ok_or("temp path not UTF-8")?;
    let obj = obj.to_str().ok_or("temp path not UTF-8")?;
    run(
        &clang,
        &[
            "--target=thumbv6m-none-eabi",
            "-mcpu=cortex-m0",
            "-mthumb",
            "-ffreestanding",
            "-nostdlib",
            "-O0",
            "-g0",
            "-c",
            src,
            "-o",
            obj,
        ],
    )?;

    let listing = run(&nm, &["-n", obj])?;
    let mut symbols = HashMap::new();
    for line in listing.lines() {
        let mut it = line.split_whitespace();
        let (Some(offset), Some(_ty), Some(name)) = (it.next(), it.next(), it.next()) else {
            continue;
        };
        if let Ok(off) = u32::from_str_radix(offset, 16) {
            symbols.insert(name.to_string(), off);
        }
    }

    let bin = dir.join("firmware.bin");
    let bin = bin.to_str().ok_or("temp path not UTF-8")?;
    run(
        &objcopy,
        &["--output-target=binary", "-j", ".text", obj, bin],
    )?;
    let bytes = fs::read(bin).map_err(|e| e.to_string())?;
    Ok((bytes, symbols))
}

/// A firmware image produced by `clang -O0` runs to its `bkpt` and leaves the
/// computed results where the C source wrote them.
#[test]
fn clang_compiled_firmware_runs() {
    let (code, symbols) = match build_firmware(FIRMWARE) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping real-firmware test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(FlatMemory::with_layout(
        &[FLASH, RAM],
        &[FLASH_LEN, RAM_LEN],
    ));
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        mem.write_word(FLASH + 8, 0).unwrap();
        mem.write_word(FLASH + 12, 0).unwrap();
        mem.write_word(IN_ADDR, 7).unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(10_000);
    assert_eq!(err, Err(HaltCause::Breakpoint));
    // sum(7) = 1+2+3+4+5+6+7 == 28.
    assert_eq!(m.core.mem().read_word(SUM_ADDR).unwrap(), 28);
    assert_eq!(m.core.mem().read_word(TAG_ADDR).unwrap(), 0xdead_beef);
}

/// A clang-compiled `SysTick_Handler` fires repeatedly off a wrapped `SysTick`
/// and returns to the interrupted thread.
#[test]
fn systick_handler_fires_and_returns() {
    let (code, symbols) = match build_firmware(SYSTICK_FIRMWARE) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping systick test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let systick = *symbols
        .get("SysTick_Handler")
        .expect("no SysTick_Handler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut sysmem = SystemMemory::new(FlatMemory::with_layout(
        &[FLASH, RAM],
        &[FLASH_LEN, RAM_LEN],
    ));
    sysmem.attach(Box::new(SysTick::new()));
    let mut m = Machine::new(sysmem);
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        mem.write_word(FLASH + 8, 0).unwrap();
        mem.write_word(FLASH + 12, 0).unwrap();
        // Vector 15 (SysTick) at FLASH + 15 * 4.
        mem.write_word(FLASH + 60, (CODE_BASE + systick) | 1)
            .unwrap();
        mem.write_word(RAM + 8, 20).unwrap(); // PERIOD
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::Breakpoint));
    // The handler ran at least three times before the firmware stopped it.
    let ticks = m.core.mem().read_word(RAM).unwrap();
    assert!(ticks >= 3, "handler ran only {ticks} times");
    assert_eq!(m.core.mem().read_word(RAM + 4).unwrap(), ticks);
}

/// On the virtual board, firmware drives GPIO outputs, reads back
/// host-injected inputs, and emits text on the UART.
#[test]
fn virtual_board_io_round_trips() {
    let (code, symbols) = match build_firmware(IO_FIRMWARE) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping virtual-board test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::virtual_board());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(board::FLASH, INIT_SP).unwrap();
        mem.write_word(board::FLASH + 4, (CODE_BASE + entry) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    // Host stimulus: pins 8..15 are high while the firmware runs.
    for device in m.core.mem().devices_mut() {
        device.drive_inputs(0x0000_5A00);
    }
    let err = m.run(10_000);
    assert_eq!(err, Err(HaltCause::Breakpoint));
    // GPIO: the output latch was driven and read back; the host-driven inputs
    // were observed on the IN register.
    assert_eq!(m.core.mem().read_word(board::RAM).unwrap(), 0xAA);
    assert_eq!(m.core.mem().read_word(board::RAM + 4).unwrap(), 0x5A00);
    // UART: the four transmitted characters reached the host channel.
    let mut tx = Vec::new();
    for device in m.core.mem().devices_mut() {
        tx.extend(device.drain_output());
    }
    assert_eq!(tx, b"Hi!\n");
}
